import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;

    static long power(long base, long exp) {
        long res = 1;
        for (; exp > 0; exp >>= 1) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
        }
        return res;
    }

    static long[] fact;

    public static long nCr(int n, int r) {
        if (n < r) return 0;
        long numerator = fact[n];
        long denominator = (fact[n - r] * fact[r]) % MOD;
        return (numerator * power(denominator, MOD - 2)) % MOD;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int maxN = 200001;
        fact = new long[maxN];
        fact[0] = 1;
        for (int i = 1; i < maxN; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        long k = Long.parseLong(input[1]);
        if (k >= n) {
            out.println(0);
            out.flush();
            return;
        }
        if (k == 0) {
            out.println(fact[n]);
            out.flush();
            return;
        }
        if (k == n - 1) {
            out.println(2L * n);
            out.flush();
            return;
        }
        int filled = (int)(n - k);
        long chooseFilled = nCr(n, filled);
        long total = 0;
        for (int empty = 0; empty <= filled; empty++) {
            long choose = nCr(filled, empty);
            long fillWays = power(filled - empty, n);
            long val = (choose * fillWays) % MOD;
            if (empty % 2 == 1) val = (MOD - val) % MOD;
            total = (total + val) % MOD;
        }
        total = (total * chooseFilled) % MOD;
        total = (total * 2) % MOD;
        out.println(total);
        out.flush();
    }
}
